// 관리자 대시보드 컴포넌트
import React, { useState, useEffect } from 'react';
import './AdminDashboard.css';
import { adminService } from '../services/adminService';
import { dummyProducts } from '../data/dummyProducts';

/**
 * AdminDashboard 컴포넌트 - 관리자 전용 대시보드
 * 사용자별 및 전체 사용자의 좋아요, 장바구니, 챗봇 대화 내역을 조회할 수 있습니다.
 * 
 * @param {boolean} isOpen - 모달이 열려있는지 여부
 * @param {Function} onClose - 모달 닫기 핸들러
 */
function AdminDashboard({ isOpen, onClose }) {
  const [activeTab, setActiveTab] = useState('overview'); // 'overview', 'favorites', 'cart', 'chat'
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [users, setUsers] = useState([]);
  const [overviewStats, setOverviewStats] = useState(null);
  const [userFavorites, setUserFavorites] = useState([]);
  const [userCarts, setUserCarts] = useState([]);
  const [userChatHistory, setUserChatHistory] = useState([]);

  // 컴포넌트 마운트 시 데이터 로드
  useEffect(() => {
    if (isOpen) {
      loadData();
    }
  }, [isOpen]);

  // 탭 변경 시 데이터 로드
  useEffect(() => {
    if (isOpen) {
      loadTabData();
    }
  }, [activeTab, selectedUserId, isOpen]);

  /**
   * 초기 데이터 로드
   */
  const loadData = () => {
    const allUsers = adminService.getAllUsers();
    setUsers(allUsers);
    setOverviewStats(adminService.getUserStats());
  };

  /**
   * 탭별 데이터 로드
   */
  const loadTabData = () => {
    if (activeTab === 'favorites') {
      if (selectedUserId) {
        const favorites = adminService.getUserFavoriteProducts(selectedUserId);
        setUserFavorites([{
          user: users.find(u => u.id === selectedUserId),
          favoriteProducts: favorites
        }]);
      } else {
        setUserFavorites(adminService.getAllUsersFavorites());
      }
    } else if (activeTab === 'cart') {
      if (selectedUserId) {
        const cart = adminService.getUserCart(selectedUserId);
        setUserCarts([{
          user: users.find(u => u.id === selectedUserId),
          cartItems: cart
        }]);
      } else {
        setUserCarts(adminService.getAllUsersCarts());
      }
    } else if (activeTab === 'chat') {
      if (selectedUserId) {
        const history = adminService.getUserChatHistory(selectedUserId);
        setUserChatHistory([{
          user: users.find(u => u.id === selectedUserId),
          chatHistory: history
        }]);
      } else {
        setUserChatHistory(adminService.getAllUsersChatHistory());
      }
    }
  };

  /**
   * 가격 포맷팅
   */
  const formatPrice = (price) => {
    return new Intl.NumberFormat('ko-KR').format(price);
  };

  /**
   * 날짜 포맷팅
   */
  const formatDate = (dateString) => {
    if (!dateString) return '-';
    const date = new Date(dateString);
    return date.toLocaleString('ko-KR', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div className="admin-dashboard-overlay" onClick={onClose}>
      <div className="admin-dashboard" onClick={(e) => e.stopPropagation()}>
        <div className="admin-dashboard-header">
          <h2>관리자 대시보드</h2>
          <button className="admin-dashboard-close" onClick={onClose} aria-label="닫기">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
              <path
                d="M18 6L6 18M6 6L18 18"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </div>

        <div className="admin-dashboard-content">
          {/* 탭 메뉴 */}
          <div className="admin-tabs">
            <button
              className={`admin-tab ${activeTab === 'overview' ? 'active' : ''}`}
              onClick={() => setActiveTab('overview')}
            >
              전체 통계
            </button>
            <button
              className={`admin-tab ${activeTab === 'favorites' ? 'active' : ''}`}
              onClick={() => setActiveTab('favorites')}
            >
              좋아요 목록
            </button>
            <button
              className={`admin-tab ${activeTab === 'cart' ? 'active' : ''}`}
              onClick={() => setActiveTab('cart')}
            >
              장바구니
            </button>
            <button
              className={`admin-tab ${activeTab === 'chat' ? 'active' : ''}`}
              onClick={() => setActiveTab('chat')}
            >
              챗봇 대화 내역
            </button>
          </div>

          {/* 사용자 선택 필터 */}
          {(activeTab === 'favorites' || activeTab === 'cart' || activeTab === 'chat') && (
            <div className="admin-user-filter">
              <label>사용자 필터:</label>
              <select
                value={selectedUserId || ''}
                onChange={(e) => setSelectedUserId(e.target.value || null)}
                className="admin-user-select"
              >
                <option value="">전체 사용자</option>
                {users.map(user => (
                  <option key={user.id} value={user.id}>
                    {user.name} ({user.email}) {user.role === 'admin' ? '[관리자]' : ''}
                  </option>
                ))}
              </select>
            </div>
          )}

          {/* 탭 컨텐츠 */}
          <div className="admin-tab-content">
            {activeTab === 'overview' && (
              <div className="admin-overview">
                <h3>전체 통계</h3>
                {overviewStats && (
                  <div className="admin-stats-grid">
                    <div className="admin-stat-card">
                      <h4>전체 사용자</h4>
                      <p className="admin-stat-value">{overviewStats.totalUsers}명</p>
                    </div>
                    <div className="admin-stat-card">
                      <h4>전체 좋아요</h4>
                      <p className="admin-stat-value">{overviewStats.totalFavorites}개</p>
                    </div>
                    <div className="admin-stat-card">
                      <h4>전체 장바구니 아이템</h4>
                      <p className="admin-stat-value">{overviewStats.totalCartItems}개</p>
                    </div>
                    <div className="admin-stat-card">
                      <h4>전체 챗봇 메시지</h4>
                      <p className="admin-stat-value">{overviewStats.totalChatMessages}개</p>
                    </div>
                  </div>
                )}
              </div>
            )}

            {activeTab === 'favorites' && (
              <div className="admin-favorites">
                <h3>
                  {selectedUserId 
                    ? `${users.find(u => u.id === selectedUserId)?.name || '사용자'}의 좋아요 목록`
                    : '전체 사용자 좋아요 목록'}
                </h3>
                {userFavorites.length === 0 ? (
                  <div className="admin-empty">데이터가 없습니다.</div>
                ) : (
                  <div className="admin-favorites-list">
                    {userFavorites.map((userData, index) => (
                      <div key={index} className="admin-user-section">
                        <h4 className="admin-user-section-title">
                          {userData.user.name} ({userData.user.email})
                        </h4>
                        {userData.favoriteProducts.length === 0 ? (
                          <p className="admin-empty-item">좋아요한 상품이 없습니다.</p>
                        ) : (
                          <div className="admin-products-grid">
                            {userData.favoriteProducts.map(product => (
                              <div key={product.product_id} className="admin-product-item">
                                <img
                                  src={product.image_url}
                                  alt={product.name}
                                  className="admin-product-image"
                                />
                                <div className="admin-product-info">
                                  <p className="admin-product-brand">{product.brand}</p>
                                  <p className="admin-product-name">{product.name}</p>
                                  <p className="admin-product-price">{formatPrice(product.price)}원</p>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'cart' && (
              <div className="admin-cart">
                <h3>
                  {selectedUserId 
                    ? `${users.find(u => u.id === selectedUserId)?.name || '사용자'}의 장바구니`
                    : '전체 사용자 장바구니'}
                </h3>
                {userCarts.length === 0 ? (
                  <div className="admin-empty">데이터가 없습니다.</div>
                ) : (
                  <div className="admin-cart-list">
                    {userCarts.map((userData, index) => (
                      <div key={index} className="admin-user-section">
                        <h4 className="admin-user-section-title">
                          {userData.user.name} ({userData.user.email})
                        </h4>
                        {userData.cartItems.length === 0 ? (
                          <p className="admin-empty-item">장바구니가 비어있습니다.</p>
                        ) : (
                          <div className="admin-cart-items">
                            {userData.cartItems.map((item, itemIndex) => (
                              <div key={itemIndex} className="admin-cart-item">
                                <img
                                  src={item.image_url}
                                  alt={item.name}
                                  className="admin-cart-item-image"
                                />
                                <div className="admin-cart-item-info">
                                  <p className="admin-cart-item-brand">{item.brand}</p>
                                  <p className="admin-cart-item-name">{item.name}</p>
                                  <p className="admin-cart-item-quantity">수량: {item.quantity}개</p>
                                  <p className="admin-cart-item-price">
                                    {formatPrice(item.price)}원 × {item.quantity} = {formatPrice(item.price * item.quantity)}원
                                  </p>
                                </div>
                              </div>
                            ))}
                            <div className="admin-cart-total">
                              <strong>
                                총 {userData.cartItems.reduce((sum, item) => sum + item.quantity, 0)}개 / 
                                {formatPrice(userData.cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0))}원
                              </strong>
                            </div>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}

            {activeTab === 'chat' && (
              <div className="admin-chat">
                <h3>
                  {selectedUserId 
                    ? `${users.find(u => u.id === selectedUserId)?.name || '사용자'}의 챗봇 대화 내역`
                    : '전체 사용자 챗봇 대화 내역'}
                </h3>
                {userChatHistory.length === 0 ? (
                  <div className="admin-empty">데이터가 없습니다.</div>
                ) : (
                  <div className="admin-chat-list">
                    {userChatHistory.map((userData, index) => (
                      <div key={index} className="admin-user-section">
                        <h4 className="admin-user-section-title">
                          {userData.user.name} ({userData.user.email})
                        </h4>
                        {userData.chatHistory.length === 0 ? (
                          <p className="admin-empty-item">대화 내역이 없습니다.</p>
                        ) : (
                          <div className="admin-chat-messages">
                            {userData.chatHistory.map((chat, chatIndex) => (
                              <div key={chatIndex} className="admin-chat-item">
                                <div className="admin-chat-message">
                                  <div className="admin-chat-message-header">
                                    <span className="admin-chat-session-id">
                                      세션: {chat.session_id || 'N/A'}
                                    </span>
                                    <span className="admin-chat-timestamp">
                                      {formatDate(chat.timestamp)}
                                    </span>
                                  </div>
                                  <div className="admin-chat-message-content">
                                    <div className="admin-chat-user-message">
                                      <strong>사용자:</strong> {chat.user_message?.content || 'N/A'}
                                    </div>
                                    <div className="admin-chat-assistant-message">
                                      <strong>챗봇:</strong> {chat.assistant_message?.content || 'N/A'}
                                    </div>
                                  </div>
                                </div>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminDashboard;

